import EntityV2 from "../abstract/entityV2";

export const ENTITY_NAME = "Subscription";

class SubscriptionEntity extends EntityV2 {
  /**
   * Get entity schema
   * @returns {Object} schema
   */
  static getSchema() {
    return {
      type: "object",
      required: ["subscription_id", "users", "expiry", "created", "data"],
      properties: {
        customer_id: {
          type: "string",
        },
        subscription_id: {
          type: "string",
        },
        users: {
          type: "integer",
        },
        email: {
          type: "string",
          format: "email",
        },
        created: {
          type: "string",
          format: "date-time",
        },
        expiry: {
          type: "string",
          format: "date-time",
        },
        data: {
          type: "string",
        },
      },
    };
  }

  /**
   * Get the expiration date.
   * @returns {string} Expiration date
   */
  get expiry() {
    return this._props.expiry;
  }

  /**
   * ==================================================
   * Serialization
   * ==================================================
   */

  /**
   * Return a DTO ready to be sent to API or content code
   * @returns {object}
   */
  toDto() {
    const result = Object.assign({}, this._props);
    return result;
  }

  /**
   * Customizes JSON stringification behavior
   * @returns {*}
   */
  toJSON() {
    return this.toDto();
  }

  /**
   * ==================================================
   * Static properties getters
   * ==================================================
   */

  /**
   * SubscriptionEntity.ENTITY_NAME
   * @returns {string}
   */
  static get ENTITY_NAME() {
    return ENTITY_NAME;
  }
}

export default SubscriptionEntity;
